package com.rescuefarm.ui.engagement;import android.os.Bundle;import android.view.*;import android.widget.*;import androidx.annotation.*;import androidx.fragment.app.Fragment;import androidx.lifecycle.ViewModelProvider;import androidx.navigation.Navigation;import com.google.firebase.auth.FirebaseAuth;import com.rescuefarm.R;import com.rescuefarm.domain.model.Favorite;import java.util.*;
public class FavoriteFragment extends Fragment{private EngagementViewModel vm;private LinearLayout box;private String uid="";@Nullable public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup p,@Nullable Bundle s){return i.inflate(R.layout.fragment_favorites,p,false);}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){uid=FirebaseAuth.getInstance().getCurrentUser()==null?"":FirebaseAuth.getInstance().getCurrentUser().getUid();box=v.findViewById(R.id.favoriteContainer);vm=new ViewModelProvider(this,new EngagementViewModelFactory(requireContext())).get(EngagementViewModel.class);vm.favorites().observe(getViewLifecycleOwner(),this::render);vm.getState().observe(getViewLifecycleOwner(),x->{if(x.getStatus()==EngagementState.Status.ERROR)Toast.makeText(requireContext(),x.getMessage(),Toast.LENGTH_LONG).show();});vm.refreshFavorites(uid);}private void render(List<Favorite> xs){box.removeAllViews();if(xs==null||xs.isEmpty()){TextView t=new TextView(requireContext());t.setText(R.string.favorites_empty);box.addView(t);return;}for(Favorite f:xs){Button b=new Button(requireContext());b.setAllCaps(false);b.setText(getString(R.string.favorite_product_format,f.getProductId()));b.setOnClickListener(v->{Bundle a=new Bundle();a.putString("productId",f.getProductId());Navigation.findNavController(requireView()).navigate(R.id.action_favoriteFragment_to_productDetailFragment,a);});box.addView(b);}}}
